INSERT INTO community_badge_definitions(key,icon,category,titles,descriptions,created_at,metric,threshold,sort_order) VALUES
('sole_treasured','heart','creation','{"zh-Hant": "萬人珍藏", "zh-Hans": "万人珍藏", "en": "Treasured by Thousands", "ja": "千人の宝物", "ko": "천 명의 보물"}','{"zh-Hant": "全站第一張被收藏 1,000 次的卡片，獎給它的作者。全站只有一位。", "zh-Hans": "全站第一张被收藏 1,000 次的卡片，奖给它的作者。全站只有一位。", "en": "Goes to the author of the first card saved 1,000 times. Only one member holds it.", "ja": "全サイトで最初に 1,000 回お気に入りされたカードの作者に贈られる。 全サイトで 1 人だけ。", "ko": "사이트에서 처음으로 1,000번 저장된 카드의 작가에게 주어져요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,300),
('sole_treasured_pioneer','heart','creation','{"zh-Hant": "萬人珍藏・先驅", "zh-Hans": "万人珍藏・先驱", "en": "Treasured by Thousands Pioneer", "ja": "千人の宝物・先駆者", "ko": "천 명의 보물 개척자"}','{"zh-Hant": "全站第 2–10 位達成「萬人珍藏」的成員（被收藏 1,000 次）。", "zh-Hans": "全站第 2–10 位达成「万人珍藏」的成员（被收藏 1,000 次）。", "en": "The 2nd to 10th members to reach Treasured by Thousands (1,000 saves on one card).", "ja": "「千人の宝物」を全サイトで 2〜10 人目に達成したメンバー（1,000 回お気に入り）。", "ko": "''천 명의 보물'' 조건(저장 1,000회)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,301),
('sole_beloved','users','creation','{"zh-Hant": "眾望所歸", "zh-Hans": "众望所归", "en": "People''s Favorite", "ja": "衆望の作者", "ko": "모두의 작가"}','{"zh-Hant": "全站第一位粉絲達到 500 人的作者。全站只有一位。", "zh-Hans": "全站第一位粉丝达到 500 人的作者。全站只有一位。", "en": "The first author to reach 500 followers. Only one member holds it.", "ja": "フォロワーが全サイトで最初に 500 人に達した作者。 全サイトで 1 人だけ。", "ko": "사이트에서 처음으로 팔로워 500명을 달성한 작가예요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,302),
('sole_beloved_pioneer','users','creation','{"zh-Hant": "眾望所歸・先驅", "zh-Hans": "众望所归・先驱", "en": "People''s Favorite Pioneer", "ja": "衆望の作者・先駆者", "ko": "모두의 작가 개척자"}','{"zh-Hant": "全站第 2–10 位達成「眾望所歸」的成員（粉絲 500 人）。", "zh-Hans": "全站第 2–10 位达成「众望所归」的成员（粉丝 500 人）。", "en": "The 2nd to 10th members to reach People''s Favorite (500 followers).", "ja": "「衆望の作者」を全サイトで 2〜10 人目に達成したメンバー（フォロワー 500 人）。", "ko": "''모두의 작가'' 조건(팔로워 500명)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,303),
('sole_founder','crown','creation','{"zh-Hant": "開山宗師", "zh-Hans": "开山宗师", "en": "Founding Master", "ja": "開山の師", "ko": "개척의 대가"}','{"zh-Hant": "全站第一位上架 30 張卡片、且其中 5 張進過榜單前十的作者。全站只有一位。", "zh-Hans": "全站第一位上架 30 张卡片、且其中 5 张进过榜单前十的作者。全站只有一位。", "en": "The first author with 30 listed cards, 5 of which have made a board''s top 10. Only one member holds it.", "ja": "掲載カード 30 枚、うち 5 枚がランキングのトップ10に入った全サイトで最初の作者。 全サイトで 1 人だけ。", "ko": "카드 30장을 공개하고 그중 5장이 랭킹 10위 안에 든 사이트 최초의 작가예요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,304),
('sole_founder_pioneer','crown','creation','{"zh-Hant": "開山宗師・先驅", "zh-Hans": "开山宗师・先驱", "en": "Founding Master Pioneer", "ja": "開山の師・先駆者", "ko": "개척의 대가 개척자"}','{"zh-Hant": "全站第 2–10 位達成「開山宗師」的成員（上架 30 張、5 張進前十）。", "zh-Hans": "全站第 2–10 位达成「开山宗师」的成员（上架 30 张、5 张进前十）。", "en": "The 2nd to 10th members to reach Founding Master (30 cards, 5 in a top 10).", "ja": "「開山の師」を全サイトで 2〜10 人目に達成したメンバー（30 枚掲載・5 枚トップ10）。", "ko": "''개척의 대가'' 조건(카드 30장·5장 톱10)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,305),
('sole_triple_crown','flame','creation','{"zh-Hant": "三連冠", "zh-Hans": "三连冠", "en": "Triple Crown", "ja": "三連覇", "ko": "3연패"}','{"zh-Hant": "全站第一位連續 3 週拿到週榜第一的作者。全站只有一位。", "zh-Hans": "全站第一位连续 3 周拿到周榜第一的作者。全站只有一位。", "en": "The first author to win a weekly board #1 three weeks in a row. Only one member holds it.", "ja": "週間ランキング 1 位を全サイトで最初に 3 週連続で獲得した作者。 全サイトで 1 人だけ。", "ko": "주간 랭킹 1위를 사이트 최초로 3주 연속 차지한 작가예요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,306),
('sole_triple_crown_pioneer','flame','creation','{"zh-Hant": "三連冠・先驅", "zh-Hans": "三连冠・先驱", "en": "Triple Crown Pioneer", "ja": "三連覇・先駆者", "ko": "3연패 개척자"}','{"zh-Hant": "全站第 2–10 位達成「三連冠」的成員（連續 3 週週榜第一）。", "zh-Hans": "全站第 2–10 位达成「三连冠」的成员（连续 3 周周榜第一）。", "en": "The 2nd to 10th members to reach Triple Crown (3 weekly #1s in a row).", "ja": "「三連覇」を全サイトで 2〜10 人目に達成したメンバー（週間 1 位を 3 週連続）。", "ko": "''3연패'' 조건(주간 1위 3주 연속)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,307),
('sole_double_crown','award','creation','{"zh-Hant": "雙料冠軍", "zh-Hans": "双料冠军", "en": "Double Champion", "ja": "二冠王", "ko": "더블 챔피언"}','{"zh-Hant": "全站第一位在同一個月同時拿下清水與綜合月榜第一的作者。全站只有一位。", "zh-Hans": "全站第一位在同一个月同时拿下清水与综合月榜第一的作者。全站只有一位。", "en": "The first author to take both the SFW and Overall monthly #1 for the same month. Only one member holds it.", "ja": "同じ月の全年齢と総合の月間 1 位を全サイトで最初に両方獲得した作者。 全サイトで 1 人だけ。", "ko": "같은 달 전연령과 종합 월간 1위를 사이트 최초로 모두 차지한 작가예요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,308),
('sole_double_crown_pioneer','award','creation','{"zh-Hant": "雙料冠軍・先驅", "zh-Hans": "双料冠军・先驱", "en": "Double Champion Pioneer", "ja": "二冠王・先駆者", "ko": "더블 챔피언 개척자"}','{"zh-Hant": "全站第 2–10 位達成「雙料冠軍」的成員（同月清水、綜合月榜第一）。", "zh-Hans": "全站第 2–10 位达成「双料冠军」的成员（同月清水、综合月榜第一）。", "en": "The 2nd to 10th members to reach Double Champion (Both monthly #1s in one month).", "ja": "「二冠王」を全サイトで 2〜10 人目に達成したメンバー（同じ月に月間 1 位を二つ）。", "ko": "''더블 챔피언'' 조건(같은 달 월간 1위 두 개)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,309),
('sole_grand_slam','crown','creation','{"zh-Hant": "大滿貫", "zh-Hans": "大满贯", "en": "Grand Slam", "ja": "グランドスラム", "ko": "그랜드슬램"}','{"zh-Hant": "全站第一位集齊全部 18 枚榜單榮譽的作者。全站只有一位。", "zh-Hans": "全站第一位集齐全部 18 枚榜单荣誉的作者。全站只有一位。", "en": "The first author to collect all 18 board honors. Only one member holds it.", "ja": "ランキング入賞バッジ 18 種を全サイトで最初にすべて集めた作者。 全サイトで 1 人だけ。", "ko": "랭킹 수상 배지 18종을 사이트 최초로 모두 모은 작가예요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,310),
('sole_grand_slam_pioneer','crown','creation','{"zh-Hant": "大滿貫・先驅", "zh-Hans": "大满贯・先驱", "en": "Grand Slam Pioneer", "ja": "グランドスラム・先駆者", "ko": "그랜드슬램 개척자"}','{"zh-Hant": "全站第 2–10 位達成「大滿貫」的成員（集齊 18 枚榜單榮譽）。", "zh-Hans": "全站第 2–10 位达成「大满贯」的成员（集齐 18 枚榜单荣誉）。", "en": "The 2nd to 10th members to reach Grand Slam (All 18 board honors).", "ja": "「グランドスラム」を全サイトで 2〜10 人目に達成したメンバー（入賞バッジ 18 種）。", "ko": "''그랜드슬램'' 조건(수상 배지 18종)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,311),
('sole_eloquent','chat','social','{"zh-Hant": "一言九鼎", "zh-Hans": "一言九鼎", "en": "Voice of Weight", "ja": "一言の重み", "ko": "천금 같은 한마디"}','{"zh-Hant": "全站第一條獲得 100 個讚的評論，獎給它的作者。全站只有一位。", "zh-Hans": "全站第一条获得 100 个赞的评论，奖给它的作者。全站只有一位。", "en": "Goes to the writer of the first comment to get 100 likes. Only one member holds it.", "ja": "全サイトで最初に 100 いいねを集めたコメントの書き手に贈られる。 全サイトで 1 人だけ。", "ko": "사이트에서 처음으로 좋아요 100개를 받은 댓글의 작성자에게 주어져요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,312),
('sole_eloquent_pioneer','chat','social','{"zh-Hant": "一言九鼎・先驅", "zh-Hans": "一言九鼎・先驱", "en": "Voice of Weight Pioneer", "ja": "一言の重み・先駆者", "ko": "천금 같은 한마디 개척자"}','{"zh-Hant": "全站第 2–10 位達成「一言九鼎」的成員（一條評論 100 個讚）。", "zh-Hans": "全站第 2–10 位达成「一言九鼎」的成员（一条评论 100 个赞）。", "en": "The 2nd to 10th members to reach Voice of Weight (100 likes on one comment).", "ja": "「一言の重み」を全サイトで 2〜10 人目に達成したメンバー（コメント 1 件に 100 いいね）。", "ko": "''천금 같은 한마디'' 조건(댓글 하나에 좋아요 100개)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,313),
('sole_wanderer','compass','play','{"zh-Hant": "千面旅人", "zh-Hans": "千面旅人", "en": "Wanderer of a Thousand Tales", "ja": "千の物語の旅人", "ko": "천 개의 이야기 여행자"}','{"zh-Hant": "全站第一位和 500 個不同角色開始過對話的成員。全站只有一位。", "zh-Hans": "全站第一位和 500 个不同角色开始过对话的成员。全站只有一位。", "en": "The first member to start conversations with 500 different characters. Only one member holds it.", "ja": "全サイトで最初に 500 人のキャラクターと会話を始めたメンバー。 全サイトで 1 人だけ。", "ko": "사이트에서 처음으로 서로 다른 캐릭터 500명과 대화를 시작한 멤버예요. 사이트 전체에서 한 명뿐이에요."}',0,NULL,NULL,314),
('sole_wanderer_pioneer','compass','play','{"zh-Hant": "千面旅人・先驅", "zh-Hans": "千面旅人・先驱", "en": "Wanderer of a Thousand Tales Pioneer", "ja": "千の物語の旅人・先駆者", "ko": "천 개의 이야기 여행자 개척자"}','{"zh-Hant": "全站第 2–10 位達成「千面旅人」的成員（和 500 個角色對話）。", "zh-Hans": "全站第 2–10 位达成「千面旅人」的成员（和 500 个角色对话）。", "en": "The 2nd to 10th members to reach Wanderer of a Thousand Tales (Chats with 500 characters).", "ja": "「千の物語の旅人」を全サイトで 2〜10 人目に達成したメンバー（500 人のキャラと会話）。", "ko": "''천 개의 이야기 여행자'' 조건(캐릭터 500명과 대화)을 사이트 2~10번째로 달성한 멤버예요."}',0,NULL,NULL,315),
('player_explorer_100','compass','play','{"zh-Hant": "閱卡無數", "zh-Hans": "阅卡无数", "en": "Seasoned traveler", "ja": "百枚の旅", "ko": "베테랑 여행자"}','{"zh-Hant": "和 100 個不同角色開始對話。", "zh-Hans": "和 100 个不同角色开始对话。", "en": "Start conversations with 100 different characters.", "ja": "100 人のキャラクターと会話を始める。", "ko": "서로 다른 캐릭터 100명과 대화를 시작하면 획득해요."}',0,'cards_played',100,316),
('player_explorer_300','compass','play','{"zh-Hant": "萬卡行者", "zh-Hans": "万卡行者", "en": "Globetrotter", "ja": "三百の旅路", "ko": "세계 일주자"}','{"zh-Hant": "和 300 個不同角色開始對話。", "zh-Hans": "和 300 个不同角色开始对话。", "en": "Start conversations with 300 different characters.", "ja": "300 人のキャラクターと会話を始める。", "ko": "서로 다른 캐릭터 300명과 대화를 시작하면 획득해요."}',0,'cards_played',300,317),
('player_follows_20','users','play','{"zh-Hant": "鐵粉", "zh-Hans": "铁粉", "en": "Devoted fan", "ja": "熱心なファン", "ko": "열혈 팬"}','{"zh-Hant": "關注 20 位作者。", "zh-Hans": "关注 20 位作者。", "en": "Follow 20 authors.", "ja": "20 人の作者をフォローする。", "ko": "작가 20명을 팔로우하면 획득해요."}',0,'follows',20,318),
('player_follows_50','users','play','{"zh-Hant": "應援團長", "zh-Hans": "应援团长", "en": "Fan club captain", "ja": "応援団長", "ko": "응원단장"}','{"zh-Hant": "關注 50 位作者。", "zh-Hans": "关注 50 位作者。", "en": "Follow 50 authors.", "ja": "50 人の作者をフォローする。", "ko": "작가 50명을 팔로우하면 획득해요."}',0,'follows',50,319),
('player_favorites_100','heart','play','{"zh-Hant": "藏書閣", "zh-Hans": "藏书阁", "en": "Archivist", "ja": "書庫の主", "ko": "서고지기"}','{"zh-Hant": "收藏 100 張卡片。", "zh-Hans": "收藏 100 张卡片。", "en": "Save 100 cards.", "ja": "100 枚のカードをお気に入りに入れる。", "ko": "카드 100장을 저장하면 획득해요."}',0,'favorites',100,320),
('player_scout_1','lantern','play','{"zh-Hant": "慧眼", "zh-Hans": "慧眼", "en": "Keen eye", "ja": "目利き", "ko": "안목"}','{"zh-Hant": "在 1 張卡片進入榜單前十之前就收藏了它，自己的卡不算。", "zh-Hans": "在 1 张卡片进入榜单前十之前就收藏了它，自己的卡不算。", "en": "Save a card before it makes a board''s top 10. Your own cards don''t count.", "ja": "ランキングのトップ10に入る前のカードを 1 枚お気に入りにする（自分のカードは除く）。", "ko": "랭킹 10위 안에 들기 전의 카드 1장을 저장하면 획득해요(내 카드 제외)."}',0,'talent_spotted',1,321),
('player_scout_5','lantern','play','{"zh-Hant": "伯樂", "zh-Hans": "伯乐", "en": "Talent scout", "ja": "名伯楽", "ko": "명백락"}','{"zh-Hant": "在 5 張卡片進入榜單前十之前就收藏了它們，自己的卡不算。", "zh-Hans": "在 5 张卡片进入榜单前十之前就收藏了它们，自己的卡不算。", "en": "Save 5 cards before they make a board''s top 10. Your own cards don''t count.", "ja": "ランキングのトップ10に入る前のカードを 5 枚お気に入りにする（自分のカードは除く）。", "ko": "랭킹 10위 안에 들기 전의 카드 5장을 저장하면 획득해요(내 카드 제외)."}',0,'talent_spotted',5,322),
('player_scout_20','lantern','play','{"zh-Hant": "點石成金", "zh-Hans": "点石成金", "en": "Kingmaker", "ja": "慧眼の主", "ko": "킹메이커"}','{"zh-Hant": "在 20 張卡片進入榜單前十之前就收藏了它們，自己的卡不算。", "zh-Hans": "在 20 张卡片进入榜单前十之前就收藏了它们，自己的卡不算。", "en": "Save 20 cards before they make a board''s top 10. Your own cards don''t count.", "ja": "ランキングのトップ10に入る前のカードを 20 枚お気に入りにする（自分のカードは除く）。", "ko": "랭킹 10위 안에 들기 전의 카드 20장을 저장하면 획득해요(내 카드 제외)."}',0,'talent_spotted',20,323),
('player_rater_10','star','play','{"zh-Hant": "評分員", "zh-Hans": "评分员", "en": "Rater", "ja": "評価係", "ko": "평가단"}','{"zh-Hant": "為 10 張卡片評分。", "zh-Hans": "为 10 张卡片评分。", "en": "Rate 10 cards.", "ja": "10 枚のカードを評価する。", "ko": "카드 10장을 평가하면 획득해요."}',0,'ratings',10,324),
('player_rater_50','star','play','{"zh-Hant": "品鑑師", "zh-Hans": "品鉴师", "en": "Connoisseur", "ja": "目利きの評者", "ko": "감정가"}','{"zh-Hant": "為 50 張卡片評分。", "zh-Hans": "为 50 张卡片评分。", "en": "Rate 50 cards.", "ja": "50 枚のカードを評価する。", "ko": "카드 50장을 평가하면 획득해요."}',0,'ratings',50,325);
